      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-003',
      customerId: 'CUST3',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-001');
  assert.equal(result[0].daysOverdue, 14);
  assert.equal(result[1].number, 'INV-003');
  assert.equal(result[1].daysOverdue, 10);
  assert.equal(result[2].number, 'INV-002');
  assert.equal(result[2].daysOverdue, 5);
});

test('overdueInvoices - mixed statuses', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST1',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-002',
      customerId: 'CUST2',
      status: 'partially_paid',
      dueDate: '2026-10-10',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 50, date: '2026-10-11' }],
    },
    {
      number: 'INV-003',
      customerId: 'CUST3',
      status: 'draft',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-004',
      customerId: 'CUST4',
      status: 'paid',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 100, date: '2026-10-06' }],
    },
  ];

  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, 'INV-001');
  assert.equal(result[1].number, 'INV-002');
});

test('overdueInvoices - multiple payments', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST1',
      status: 'partially_paid',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 500, discountPercent: 0, vatRate: 0 }],
